const results=[];
for(const item of $input.all()){
  const data=item.json;
  const job_id='job_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10);
  let n={source:null,origin_channel:null,user_id:null,chat_id:null,requester_email:null,raw_text:'',voice_file_id:null,job_id:job_id,timestamp:new Date().toISOString()};
  if(data.message||data.edited_message||data.callback_query){
    n.source='telegram';n.origin_channel='telegram';
    const msg=data.message||data.edited_message||data.callback_query?.message;
    const from=data.message?.from||data.edited_message?.from||data.callback_query?.from;
    n.user_id=from?.id?.toString()||null;
    n.chat_id=msg?.chat?.id?.toString()||null;
    if(data.callback_query){n.raw_text=data.callback_query.data||'';}
    else if(msg?.voice){n.voice_file_id=msg.voice.file_id;n.raw_text=msg.caption||'';}
    else{n.raw_text=msg?.text||msg?.caption||'';}
  }else if(data.subject!==undefined||data.from){
    n.source='email';n.origin_channel='email';
    const fa=data.from?.value?.[0]?.address||data.from?.text||data.from||'';
    const addr=typeof fa==='string'?fa:'email_user';
    n.user_id=addr;n.requester_email=addr;n.chat_id=null;
    n.raw_text=(data.subject||'')+' '+(data.text||data.textPlain||'');
  }else if(data.raw_text){
    n.source='sheets';n.origin_channel='email';
    n.user_id=data.user_id||'sheets_user';n.requester_email=data.requester_email||data.user_id||null;n.chat_id=data.chat_id||null;
    n.raw_text=data.raw_text||'';
  }
  if(n.raw_text||n.voice_file_id){results.push({json:n});}
}
return results.length>0?results:[{json:{source:'empty',origin_channel:null,raw_text:'',user_id:null,chat_id:null,requester_email:null,voice_file_id:null,job_id:'job_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10),timestamp:new Date().toISOString()}}];

const prev=$('Normalize Input').first()?.json||{};
const job_id=prev.job_id||('job_'+Date.now().toString(36)+'_'+Math.random().toString(36).slice(2,10));
let parsedData=null;
let parse_error=null;
const rawContent=$input.first()?.json?.choices?.[0]?.message?.content;
if(!rawContent||rawContent.trim()===''){parse_error='CLASSIFIER_EMPTY_RESPONSE';}
else{try{const cleanRaw=rawContent.replace(/```json/gi,'').replace(/```/g,'').trim();parsedData=JSON.parse(cleanRaw);}catch(e){parse_error='CLASSIFIER_PARSE_FAILED';}}
function normText(v){let s=String(v||'');try{s=s.normalize('NFKC');}catch(e){}return s.replace(/\u00a0/g,' ').replace(/ё/g,'е').replace(/\s+/g,' ').trim();}
function extractRequestedCount(text){
  const s=normText(text);
  const found=new Set();
  const nouns='(?:заказ(?:а|ы|ов)?|заяв(?:ка|ки|ок)|тендер(?:а|ы|ов)?|закуп(?:ка|ки|ок)|лид(?:а|ы|ов)?|результат(?:а|ы|ов)?|контакт(?:а|ы|ов)?)';
  const before=new RegExp('(^|[^\\p{L}\\p{N}])(\\d{1,4})(?![\\d.,])(?:\\s+[\\p{L}\\p{M}-]+){0,5}\\s+'+nouns+'(?![\\p{L}\\p{M}-])','giu');
  const after=new RegExp('(?:^|[^\\p{L}\\p{N}])'+nouns+'(?:\\s+[\\p{L}\\p{M}-]+){0,3}\\s+(\\d{1,4})(?![\\d.,])','giu');
  function accept(raw){const n=Number(raw);if(!Number.isSafeInteger(n)||n<=0||n>500)return;if(n>=1900&&n<=2100)return;found.add(n);}
  let m;while((m=before.exec(s))!==null)accept(m[2]);
  while((m=after.exec(s))!==null)accept(m[m.length-1]);
  const vals=Array.from(found);
  if(vals.length===0)return{requested_count:null,ambiguous:false};
  if(vals.length>1)return{requested_count:null,ambiguous:true};
  return{requested_count:vals[0],ambiguous:false};
}
function isNationalTenderPhrase(text){const n=normText(text).toLowerCase();return /(^|[^а-яa-z0-9])(по\s+всей\s+россии|по\s+россии|в\s+россии|вся\s+россия|рф|российская\s+федерация|российской\s+федерации)([^а-яa-z0-9]|$)/i.test(n);}
const rc=extractRequestedCount(prev.raw_text||'');
const intent=(parsedData&&parsedData.intent)?parsedData.intent:'unknown';
const entities=(parsedData&&parsedData.entities&&typeof parsedData.entities==='object')?parsedData.entities:{};
let region_scope='UNKNOWN';
if(intent==='tender_search'&&isNationalTenderPhrase(prev.raw_text||'')){entities.region='Россия';region_scope='NATIONAL';}
else if(entities.region!=null&&String(entities.region).trim()!==''){region_scope='LOCAL';}
return [{json:{
  job_id:job_id,created_at:new Date().toISOString(),started_at:new Date().toISOString(),source:prev.source||'unknown',origin_channel:prev.origin_channel||null,user_id:prev.user_id||null,chat_id:prev.chat_id||null,requester_email:prev.requester_email||null,raw_text:prev.raw_text||'',intent:intent,entities:entities,region_scope:region_scope,confidence:(parsedData&&typeof parsedData.confidence==='number')?parsedData.confidence:0,parse_error:parse_error,requested_count:rc.requested_count,requested_count_ambiguous:rc.ambiguous,status:'processing'
}}];

const item=$input.first()?.json||{};
const intent=item.intent;
const entities=item.entities||{};
const service=(entities.service!=null)?String(entities.service).trim():'';
const region=(entities.region!=null)?String(entities.region).trim():'';
let regionScope=String(item.region_scope||'UNKNOWN').toUpperCase();
function normRegion(r){return String(r||'').toLowerCase().replace(/ё/g,'е').replace(/\s+/g,' ').trim();}
function isGenericNationwide(r){const n=normRegion(r);return /^(россия|рф|российская федерация|вся россия|по всей россии|вся рф|по всей рф|по россии|в россии)$/.test(n);}
function hasNationwidePhrase(t){const n=normRegion(t);return /(^|[^а-яa-z0-9])(по всей россии|по россии|в россии|вся россия|рф|российская федерация|российской федерации)([^а-яa-z0-9]|$)/i.test(n);}
if(intent==='tender_search'&&hasNationwidePhrase(item.raw_text||'')){regionScope='NATIONAL';entities.region='Россия';}
else if(region&&regionScope==='UNKNOWN')regionScope='LOCAL';
const RECOGNIZED=['search_private','search_b2b','company_analysis','tender_search','site_analysis','deep_osint'];
const CONTAINED=['search_b2b','company_analysis','site_analysis','deep_osint'];
let route_action;let error_code=null;let error_message_ru=null;
if(item.requested_count_ambiguous===true){route_action='failed';error_code='AMBIGUOUS_REQUESTED_COUNT';error_message_ru='В запросе найдено несколько разных количеств результатов. Укажите одно число.';}
else if(!RECOGNIZED.includes(intent)){route_action='unsupported';error_code='UNSUPPORTED_INTENT';}
else if(CONTAINED.includes(intent)){route_action='unsupported';error_code='CONTAINED_ROUTE';}
else if(intent==='search_private'){
  if(!service){route_action='failed';error_code='MISSING_SERVICE';error_message_ru='Для поиска частных заказов укажите услугу.';}
  else if(!region){route_action='failed';error_code=hasNationwidePhrase(item.raw_text)?'GENERIC_REGION_NOT_SPECIFIC':'MISSING_REGION';error_message_ru='Для поиска частных заказов укажите конкретный город или регион.';}
  else if(isGenericNationwide(region)){route_action='failed';error_code='GENERIC_REGION_NOT_SPECIFIC';error_message_ru='Для поиска частных заказов нужен конкретный город или регион, а не вся Россия.';}
  else{regionScope='LOCAL';route_action='search_private';}
}
else if(intent==='tender_search'){
  if(!service){route_action='failed';error_code='MISSING_SERVICE';error_message_ru='Для поиска тендеров укажите услугу или вид работ.';}
  else if(regionScope==='NATIONAL'){entities.region='Россия';route_action='tender_search';}
  else if(region){regionScope='LOCAL';route_action='tender_search';}
  else{route_action='failed';error_code='MISSING_TENDER_REGION_SCOPE';error_message_ru='Для поиска тендеров укажите конкретный регион или явно запросите поиск по России.';}
}
else{route_action='unsupported';error_code='UNSUPPORTED_INTENT';}
return [{json:Object.assign({},item,{entities:entities,region_scope:regionScope,route_action:route_action,error_code:error_code,error_message_ru:error_message_ru,contract_ok:(route_action==='search_private'||route_action==='tender_search')})}];

const item=$input.first()?.json||{};
const job=$('Parse Intent').first().json||{};
const s=(item.status!=null)?String(item.status).toLowerCase():'';
const isSuccess=(s==='done'||s==='no_results');
const hasError=!!(item.error||item.errorMessage||item.executionError);
const failed=hasError||!isSuccess;
return [{json:Object.assign({},job,{route_action:failed?'failed':'search_private_complete',error_code:failed?'CHILD_WORKFLOW_FAILED':null})}];
